const config = { mode: "dark" };
Object.defineProperty(config, "version", { value: 3 });

console.log(Reflect.set(config, "version", 4), config.version);
console.log(Reflect.set(config, "mode", "light"), config.mode);
console.log(Reflect.deleteProperty(config, "version"));
